// def __iter__(self) -> Iterator[K]:
//     for k in self._d:
//         yield k                     # -> S_RESUME_0
template <::tpystd::tpy::Hashable K, typename V>
std::expected<::tpy::yield_slot_t<K>, ::tpy::StopIteration> __gen_Base___iter__<K, V>::__next__() {
    while (true) switch (__state) {
    case S_INITIAL: {  // entry
        __state = S_DONE;  // until a yield sets where to resume
        auto& __for_obj_0 = __self._d;
        __for_it_0.emplace((__for_obj_0).begin());
        __for_end_0.emplace((__for_obj_0).end());
        __state = S_JOIN_0;
        continue;
    }
    case S_RESUME_0:  // after: yield k
    case S_JOIN_0: {
        if ((*__for_it_0) == (*__for_end_0)) {
            __state = S_DONE;
            return ::tpy::make_unexpected(::tpy::StopIteration{});
        }
        k = &(*((*__for_it_0))++);
        __state = S_RESUME_0;
        return (*k);
    }
    case S_DONE: return ::tpy::make_unexpected(::tpy::StopIteration{});
    }
    __builtin_unreachable();
}


template <::tpystd::tpy::Hashable K, typename V>
inline __gen_Base___iter__<K, V> Base<K, V>::__iter__() {
    return __gen_Base___iter__<K, V>(*this);
}

